 check('mesh_separate_contract',len({c['contract_design_sha256'] for c in cases})==2 and all(c['mesh_nm']==5 for c in normal))
 # Exact carrier round-trip, no model fitting or truth alignment.
 wave=np.arange(440,461)[:,None,None];m=np.arange(-3,4)[None,:,None];kz=np.sqrt((2*np.pi/wave)**2-(2*np.pi*m/1740)**2)
